head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.comCd = ""; // 기업코드
scwin.basYymm = ""; // 결산년월

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    try {
       scwin.param = $c.data.getParameter();

       scwin.comCd = scwin.param.comCd; 
       scwin.basYymm = scwin.param.basYymm; 

       scwin.search(); // 조회
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00300_P1.onpageload" });
    }
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// 팝업닫기
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00300_P1.img_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_AudtOpinRes.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    return true;
};

/**
 * 감사의견 팝업 조회
 */
scwin.search = async function() {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;ㄱ
    }
    // 임시 팝업 붙이면 제거
    // scwin.comCd = "803782";   //제일 교통주
    // scwin.basYymm = "2020-12";

    let url = "/api/listing/nice/individual-notes/audit-opinion/opinion-detail?kisCd="+scwin.comCd+"&acntclsDt="+scwin.basYymm;
    await $c.sbm.setAction(sbm_dlt_AudtOpin, url);
    await $c.sbm.execute(sbm_dlt_AudtOpin);
    scwin.appendContents();
};

/**
 * 컨텐츠 append
 */
scwin.appendContents = function() {
    let strContent = "<div style='overflow-x:hidden;width:100%;height:410px;font-family:돋움체;'>";
    for (let nRow = 0; nRow <= dlt_AudtOpinRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_AudtOpinRes.getCellData(nRow, "audtOpin");
    }
    strContent = strContent + "</div>";

    let grpCtntObj = $p.getComponentById("grp_Ctnt").render;

    grpCtntObj.innerHTML = strContent;
    grp_Ctnt.setStyle("border", "1px solid blue");
    grp_Ctnt.setStyle("magin-top", "30px");
};
